package reporting

import (
	"encoding/binary"
	"unicode/utf16"
	"unicode/utf8"
)

type ExportWriter struct {
	Writer io.Writer
}

func NewExportWriter(w io.Writer) *ExportWriter {
	return &ExportWriter{
		Writer: w,
	}
}

func (ew *ExportWriter) WriteByte(b byte) error {
	_, err := ew.Writer.Write([]byte{b})
	return err
}

func (ew *ExportWriter) WriteBytes(bs []byte) error {
	_, err := ew.Writer.Write(bs)
	return err
}

func (ew *ExportWriter) WriteString(s string) error {
	bs := utf16.Encode([]rune(s))
	return ew.WriteBytes(bs)
}

func (ew *ExportWriter) WriteUTF16LE(s string) error {
	bs := make([]byte, 2*(utf8.RuneCountInString(s)+1))
	bs[0] = 0xFEFF // Byte order mark
	i := 1
	for _, r := range []rune(s) {
		runes := utf16.Encode([]rune{r})
		for j := 0; j < len(runes); j++ {
			bs[i] = runes[j]
			i++
		}
	}
	return ew.WriteBytes(bs)
}
